            flex-direction: column;
            justify-content: space-between;
            padding: 20px;
        }

        /* Enable pointer events for interactive UI elements */
        .interactive {
            pointer-events: auto;
        }

        /* Header Area */
        header {
            display: flex;
            justify-content: space-between;
            align-items: flex-start;
        }

        .header-left h1 {
            font-size: 16px;
            font-weight: 600;
