            align-items: flex-end;
        }

        /* Info Card */
        .info-card {
            background: var(--panel-bg);
            backdrop-filter: blur(10px);
            width: 380px;
            padding: 20px;
            border-radius: 12px;
            border: 1px solid rgba(255,255,255,0.05);
            box-shadow: 0 4px 20px rgba(0,0,0,0.5);
