        }

        .card-desc {
            font-size: 13px;
            line-height: 1.6;
            color: #ccc;
            margin-bottom: 20px;
        }

        .card-footer {
            font-size: 11px;
            color: var(--text-secondary);
            border-top: 1px solid rgba(255,255,255,0.1);
            padding-top: 12px;
            font-style: italic;
        }

        /* Dimensions & Controls */
        .bottom-right {
            display: flex;
            flex-direction: column;
            align-items: flex-end;
            gap: 15px;
        }

        .dimensions {
            background: rgba(255, 255, 255, 0.1);
            padding: 6px 12px;
            border-radius: 6px;
            font-family: monospace;
            font-size: 12px;
            color: var(--text-primary);
        }

        .controls-hint {
            display: flex;
            align-items: center;
            gap: 8px;
            font-size: 11px;
            color: var(--text-secondary);
        }

        .compass {
            width: 24px;
            height: 24px;
            border: 1px solid var(--text-secondary);
            border-radius: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 10px;
            font-weight: bold;
        }

        /* Responsive */
        @media (max-width: 768px) {
            .info-card {
                width: calc(100% - 40px);
                max-height: 40vh;
                overflow-y: auto;
            }
            .sub-header {
                flex-direction: column;
                align-items: flex-start;
                gap: 15px;
            }
        }
    </style>
</head>
<body>

    <!-- 3D Canvas Container -->
    <div id="canvas-container"></div>

    <!-- UI Overlay -->
    <div class="ui-layer">

        <!-- Top Section -->
        <div>
            <header class="interactive">
                <div class="header-left">
                    <h1>
                        <span class="back-btn">←</span> 
                        E-101 • WASTE HEAT BOILER
                    </h1>
                    <p>Steam-Methane Reforming Plant · 3D component model</p>
                </div>
                <div class="settings-icon">⚙</div>
            </header>

            <div class="sub-header interactive">
                <div class="chip-group">
                    <div class="chip">3D COMPONENT MODEL</div>
                    <div class="chip" style="border-color: rgba(255,255,255,0.2);">E-101</div>
                    <div class="chip">REAL SCALE</div>
                </div>

                <div class="toggle-switch" id="viewToggle">
                    <div class="toggle-option active" data-view="assembled">ASSEMBLED</div>
                    <div class="toggle-option" data-view="cutaway">CUTAWAY</div>
                </div>
            </div>
        </div>

        <!-- Bottom Section -->
        <footer>
            <!-- Info Card -->
            <div class="info-card interactive">
                <div class="card-header">
                    <span class="card-label">The Component</span>
                    <span class="close-btn">×</span>
                </div>
                <h2 class="card-title">Shell-and-tube heat exchanger</h2>
                <p class="card-desc">
                    The workhorse of every chemical plant. One fluid flows through a bundle of parallel tubes sealed inside a cylindrical shell; another flows across the outside of those tubes, guided up and over the segmental baffles. The two streams never mix — heat simply moves through the tube walls. Green nozzles carry the shell side, red the tube side, and the cutaway opens the shell exactly like the sectioned twin of the training unit.
                </p>
                <div class="card-footer">
                    Modeled in-app after photos of the shell-and-tube training unit
                </div>
            </div>

            <!-- Bottom Right Controls -->
            <div class="bottom-right interactive">
                <div class="dimensions" id="dimDisplay">0.82 × 1.08 × 3.24 m</div>

                <div class="controls-hint">
                    <div class="compass">N</div>
                    <span>to orbit · scroll to zoom</span>
                </div>
            </div>
        </footer>
    </div>

    <!-- Scripts -->
    <script type="importmap">
        {
            "imports": {
                "three": "https://unpkg.com/three@0.160.0/build/three.module.js",
                "three/addons/": "https://unpkg.com/three@0.160.0/examples/jsm/"
            }
        }
    </script>

    <script type="module">
        import * as THREE from 'three';
        import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

        // --- Configuration ---
        const CONFIG = {
            shellLength: 4,
            shellRadius: 0.8,
            nozzleRadius: 0.15,
            nozzleHeight: 0.4,
            colors: {
                metal: 0x888888,
                metalDark: 0x444444,
                green: 0x2ecc71,
                red: 0xe74c3c,
                grid: 0x333333
            }
        };

        // --- Scene Setup ---
        const container = document.getElementById('canvas-container');
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x1a1a1a);

        // Camera
        const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 100);
        camera.position.set(5, 3, 6);

        // Renderer
        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
        renderer.shadowMap.enabled = true;
        renderer.shadowMap.type = THREE.PCFSoftShadowMap;
        container.appendChild(renderer.domElement);

        // Controls
        const controls = new OrbitControls(camera, renderer.domElement);
        controls.enableDamping = true;
        controls.dampingFactor = 0.05;
        controls.target.set(0, 0.5, 0); // Look slightly above origin

        // --- Lighting ---
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.4);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 1.2);
        dirLight.position.set(5, 10, 7);
        dirLight.castShadow = true;
        dirLight.shadow.mapSize.width = 2048;
        dirLight.shadow.mapSize.height = 2048;
        scene.add(dirLight);

        const fillLight = new THREE.DirectionalLight(0xeeeeee, 0.5);
        fillLight.position.set(-5, 5, -5);
        scene.add(fillLight);

        // --- Grid ---
        // Custom Grid to match dark industrial look
        const gridHelper = new THREE.GridHelper(20, 20, 0x444444, 0x222222);
        scene.add(gridHelper);

        // --- Materials ---
        const matMetal = new THREE.MeshStandardMaterial({ 
            color: CONFIG.colors.metal, 
            roughness: 0.3, 
            metalness: 0.7 
        });

        const matMetalDark = new THREE.MeshStandardMaterial({ 
            color: CONFIG.colors.metalDark, 
            roughness: 0.8, 
            metalness: 0.2 
        });

        const matGreen = new THREE.MeshStandardMaterial({ 
            color: CONFIG.colors.green, 
            roughness: 0.4 
        });

        const matRed = new THREE.MeshStandardMaterial({ 
            color: CONFIG.colors.red, 
            roughness: 0.4 
        });

        // --- Geometry Construction ---
        const exchangerGroup = new THREE.Group();

        // 1. Main Shell (Cylinder)
        // Length 4, Radius 0.8. Centered at Y=0.8 so it rests on grid (Y=0)
        const shellGeo = new THREE.CylinderGeometry(CONFIG.shellRadius, CONFIG.shellRadius, CONFIG.shellLength, 32);
        const shellMesh = new THREE.Mesh(shellGeo, matMetal);
        shellMesh.rotation.z = Math.PI / 2; // Rotate to lie along Z axis
        shellMesh.position.y = CONFIG.shellRadius; // Lift radius amount to sit on ground
        shellMesh.castShadow = true;
        shellMesh.receiveShadow = true;
        exchangerGroup.add(shellMesh);

        // 2. Heads (Hemispheres / Domes)
        const headGeo = new THREE.SphereGeometry(CONFIG.shellRadius, 32, 16, 0, Math.PI * 2, 0, Math.PI / 2);

        // Front Head
        const headFront = new THREE.Mesh(headGeo, matMetal);
        headFront.rotation.z = -Math.PI / 2; // Flip orientation
        headFront.position.set(-CONFIG.shellLength/2, CONFIG.shellRadius, 0);
        headFront.castShadow = true;
        exchangerGroup.add(headFront);

        // Rear Head
        const headRear = new THREE.Mesh(headGeo, matMetal);
        headRear.rotation.z = Math.PI / 2;
        headRear.position.set(CONFIG.shellLength/2, CONFIG.shellRadius, 0);
        headRear.castShadow = true;
        exchangerGroup.add(headRear);

        // 3. Flanges (Rings around heads)
        const flangeGeo = new THREE.TorusGeometry(CONFIG.shellRadius + 0.05, 0.05, 16, 32);
        const flangeMat = matMetalDark;

        const flangeFront = new THREE.Mesh(flangeGeo, flangeMat);
        flangeFront.position.set(-CONFIG.shellLength/2 + 0.1, CONFIG.shellRadius, 0);
        flangeFront.rotation.y = Math.PI / 2;
        exchangerGroup.add(flangeFront);

        // 4. Nozzles Helper Function
        function createNozzle(x, y, z, colorMat, isVertical = true) {
            const group = new THREE.Group();

            // Nozzle Pipe
            const pipeGeo = new THREE.CylinderGeometry(CONFIG.nozzleRadius, CONFIG.nozzleRadius, CONFIG.nozzleHeight, 16);
            const pipe = new THREE.Mesh(pipeGeo, colorMat);
            pipe.position.y = CONFIG.nozzleHeight / 2;
            pipe.castShadow = true;
            group.add(pipe);

            // Flange on top
            const flangeGeoSmall = new THREE.CylinderGeometry(CONFIG.nozzleRadius * 1.6, CONFIG.nozzleRadius * 1.6, 0.05, 16);
            const flange = new THREE.Mesh(flangeGeoSmall, matMetalDark);
            flange.position.y = CONFIG.nozzleHeight;
            group.add(flange);

            // Positioning
            group.position.set(x, y, z);

            if (!isVertical) {
                 // For horizontal nozzles (if needed), rotate logic goes here
            }

            return group;
        }

        // Add Nozzles based on requirements:
        // Green: Top of shell (2)
        // Red: Front-Bottom, Rear-Top

        // Green 1 (Top Left-ish)
        const nGreen1 = createNozzle(-1, CONFIG.shellRadius * 2, 0, matGreen);
        exchangerGroup.add(nGreen1);

        // Green 2 (Top Right)
        const nGreen2 = createNozzle(1.2, CONFIG.shellRadius * 2, 0, matGreen);
        exchangerGroup.add(nGreen2);

        // Red 1 (Front Bottom) - Attached to Front Head area
        // Note: y is near 0 (ground)
        const nRed1 = createNozzle(-CONFIG.shellLength/2 + 0.2, 0.1, 0, matRed); 
        exchangerGroup.add(nRed1);

        // Red 2 (Rear Top) - Attached to Rear Head area
        const nRed2 = createNozzle(CONFIG.shellLength/2 - 0.2, CONFIG.shellRadius * 2, 0, matRed);
        exchangerGroup.add(nRed2);


        // 5. Saddle Supports (Base)
        function createSaddle(zPos) {
            const saddleGroup = new THREE.Group();

            // Base Plate
            const baseGeo = new THREE.BoxGeometry(1.2, 0.1, 0.8);
            const base = new THREE.Mesh(baseGeo, matMetalDark);
            base.position.y = 0.05;
            saddleGroup.add(base);

            // Vertical Support
            const vertGeo = new THREE.BoxGeometry(0.8, CONFIG.shellRadius - 0.1, 0.6);
            const vert = new THREE.Mesh(vertGeo, matMetalDark);
            vert.position.y = (CONFIG.shellRadius) / 2;
            saddleGroup.add(vert);

            // Curved top part (simplified box for now or arc)
            // Let's use an arc geometry or just a box that touches
            const topGeo = new THREE.BoxGeometry(0.8, 0.4, 0.6);
            const top = new THREE.Mesh(topGeo, matMetalDark);
            top.position.y = CONFIG.shellRadius - 0.2;
            saddleGroup.add(top);

            saddleGroup.position.z = zPos;
            return saddleGroup;
        }

        exchangerGroup.add(createSaddle(1.0));
        exchangerGroup.add(createSaddle(-1.0));

        // Add entire model to scene
        scene.add(exchangerGroup);

        // --- Interaction Logic (Cutaway Toggle) ---
        let isCutaway = false;
        const toggleOptions = document.querySelectorAll('.toggle-option');
        const toggleContainer = document.getElementById('viewToggle');

        toggleContainer.addEventListener('click', () => {
            isCutaway = !isCutaway;

            // Update UI
            toggleOptions.forEach(opt => {
                opt.classList.remove('active');
                if ((isCutaway && opt.dataset.view === 'cutaway') || 
                    (!isCutaway && opt.dataset.view === 'assembled')) {
                    opt.classList.add('active');
                }
            });

            // Animate Model
            // Simple implementation: Scale X to 0 or hide parts
            // For a real cutaway we would clip planes, but here we will simulate 
            // by scaling the shell mesh down or hiding it to reveal "insides".
            // Since we didn't build complex internals (tubes), we'll just scale the shell 
            // to look like it's opening, or simply toggle visibility of the shell to show "ghost" effect.

            // Let's do a clip plane effect via shader or just scale shell for this demo
            if (isCutaway) {
                // Animate shell scale X to 0.8 and move
                gsapLike(shellMesh.scale, { x: 0.01, z: 0.01 }, 500); // Collapse shell
                gsapLike(headFront.scale, { x: 0.01, y: 0.01, z: 0.01 }, 500);
                gsapLike(headRear.scale, { x: 0.01, y: 0.01, z: 0.01 }, 500);
            } else {
                gsapLike(shellMesh.scale, { x: 1, z: 1 }, 500);
                gsapLike(headFront.scale, { x: 1, y: 1, z: 1 }, 500);
                gsapLike(headRear.scale, { x: 1, y: 1, z: 1 }, 500);
            }
        });

        // Simple animation helper
        function gsapLike(target, props, duration) {
            const start = performance.now();
            const initial = {};
            for(let k in props) initial[k] = target[k];

            function update() {
                const elapsed = performance.now() - start;
                const progress = Math.min(elapsed / duration, 1);
                // Ease out cubic
                const ease = 1 - Math.pow(1 - progress, 3);

                for(let k in props) {
                    target[k] = initial[k] + (props[k] - initial[k]) * ease;
                }

                if (progress < 1) requestAnimationFrame(update);
            }
            requestAnimationFrame(update);
        }


        // --- Resize Handler ---
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        // --- Animation Loop ---
        function animate() {
            requestAnimationFrame(animate);
            controls.update();
            renderer.render(scene, camera);
        }

        animate();

    </script>
</body>
</html>
